def glob(pattern, text):
    # your code
    pass

practice.solution:
def glob(pattern, text):
    parts = pattern.split('*')
    if len(parts) == 1:
        return pattern == text
    if not text.startswith(parts[0]):
        return False
    pos = len(parts[0])
    for mid in parts[1:-1]:
        i = text.find(mid, pos)
        if i < 0:
            return False
        pos = i + len(mid)
    last = parts[-1]
    if len(text) - pos < len(last):
        return False
    return text.endswith(last)

