def glob(pattern, text):
    parts = pattern.split('*')
    if len(parts) == 1:
        return pattern == text
    if not text.startswith(parts[0]):
        return False
    pos = len(parts[0])
    for mid in parts[1:-1]:
        i = text.find(mid, pos)
        if i < 0:
            return False
        pos = i + len(mid)
    last = parts[-1]
    if len(text) - pos < len(last):
        return False
    return text.endswith(last)
def decide(allow, deny, target, destructive):
    for d in deny:
        if glob(d, target):
            return 'deny'
    matched = False
    for a in allow:
        if glob(a, target):
            matched = True
    if matched and not destructive:
        return 'allow'
    return 'confirm'

