def run(tasks, mode):
    events = []
    done = []
    for name, ok, has_undo in tasks:
        if ok:
            events.append('ran:' + name)
            done.append([name, has_undo])
        else:
            events.append('failed:' + name)
            if mode == 'stop':
                return events
            if mode == 'rollback':
                for n, u in reversed(done):
                    if u:
                        events.append('undo:' + n)
                return events
    return events

